def build_catalog(database_crops, database_soils):
    crops = {key: {**value, **CROP_DETAILS.get(key, {})} for key, value in database_crops.items()}
    for key, value in CROP_DETAILS.items():
        if key not in crops and "name" in value:
            crops[key] = value.copy()

    soils = {key: {**value, **SOIL_DETAILS.get(key, {})} for key, value in database_soils.items()}
    for key, value in SOIL_DETAILS.items():
        if key not in soils and "name" in value:
            soils[key] = value.copy()
    return crops, soils
